76	  } = useAuthStore();
77	
78	  const [isLoggingIn, setIsLoggingIn] = useState(false);
79	  const [isLoggingOut, setIsLoggingOut] = useState(false);
80	  const restoringRef = useRef(false);
81	
82	  // Stable refs for functions used in the session restoration effect.
83	  // This prevents the effect from re-firing when function references change.
84	  const initializeOrLoadVaultRef = useRef<(() => Promise<void>) | null>(null);
85	  const coreKitLogoutRef = useRef<(() => Promise<void>) | null>(null);
