171	        const vaultKeyIpnsName = vaultKeyKeypair.ipnsName;
172	
173	        // 1. Publish v2 key blob to vault key IPNS (rootFolderKey storage — key only, no metadata)
174	        const encryptedRootFolderKey = await wrapKey(newVault.rootFolderKey, userKeypair.publicKey);
175	        const v2Blob = serializeVaultBlobV2(encryptedRootFolderKey);
176	
177	        const keyBlobUpload = await addToIpfs(new Blob([v2Blob as BlobPart]));
178	        const keyPublishResult = await createAndPublishIpnsRecord({
179	          ipnsPrivateKey: vaultKeyKeypair.privateKey,
180	          ipnsName: vaultKeyIpnsName,
181	          metadataCid: keyBlobUpload.cid,
182	          sequenceNumber: 0n,
183	          expectedSequenceNumber: undefined,
