185	        if (!keyPublishResult.success) {
186	          throw new Error('Failed to publish vault key blob to IPNS');
187	        }
188	
189	        // 2. Publish folder metadata using v1 encrypted envelope format on IPFS ({iv, data});
190	        //    FolderMetadata.version remains 'v2' (metadata schema version).
191	        const emptyMetadata: FolderMetadata = { version: 'v2', children: [] };
192	        const encrypted = await encryptFolderMetadata(emptyMetadata, newVault.rootFolderKey);
193	        const metadataBlob = new Blob([JSON.stringify(encrypted)], { type: 'application/json' });
194	        const metadataUpload = await addToIpfs(metadataBlob);
195	        const folderPublishResult = await createAndPublishIpnsRecord({
